(()=>{const main=document.querySelector('main');if(!main||location.pathname.startsWith('/ar/'))return;const feat=['Instant activation','Up to +22,000 channels','Up to +88,000 VODs & Series','0.1 Credit = 1 Month','0.3 Credit = 3 Months','0.5 Credit = 6 Months','1 Credit = 12 Months','24/7 support','Full API access','Own custom domain support'];const style=document.createElement('style');style.textContent='.split-smart{display:grid;grid-template-columns:1.05fr .95fr;gap:46px;align-items:center}.reseller-smart{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}.reseller-smart .card{padding:20px}.reseller-smart .list{font-size:.8rem}.slide{display:none}.slide.active{display:block;animation:fade .55s ease}.slider-dots{display:flex;gap:8px;margin-top:25px}.slider-dots button{width:10px;height:10px;border:0;border-radius:50%;background:#7180b9}.slider-dots button.active{background:#fff;width:28px;border-radius:8px}.faq-smart details{border-bottom:1px solid #34416f;padding:17px 0}.faq-smart summary{font-weight:800;cursor:pointer}.faq-smart p{color:#b9c5e5}@keyframes fade{from{opacity:.25;transform:translateY(8px)}to{opacity:1;transform:none}}@media(max-width:900px){.split-smart,.reseller-smart{grid-template-columns:1fr}}';document.head.append(style);function cards(){return feat.map(x=>'<li>'+x+'</li>').join('')}if(location.pathname==='/reseller/'){main.innerHTML='<section class="pagehead"><div class="wrap"><span class="eyebrow">Reseller & panel tools</span><h1>Tivione IPTV Reseller Packages</h1><p class="lead">Choose a package built around flexible credits, professional server features and scalable operations.</p></div></section><section><div class="wrap"><div class="reseller-smart">'+[['10 Credits','€190','Start with a focused credit package.'],['20 Credits','Contact sales','Build steady momentum.'],['50 Credits','Contact sales','Support a broader customer base.'],['100 Credits','Contact sales','Scale your operation.'],['Grow package','Contact sales','Create a tailored volume plan.']].map(([n,p,d])=>'<article class="card"><span class="eyebrow">Reseller package</span><h3>'+n+'</h3><div class="price">'+p+'</div><p>'+d+'</p><ul class="list">'+cards()+'</ul><a class="button" href="https://wa.me/212670779271?text='+encodeURIComponent('Hello Tivione IPTV, I am interested in: '+n)+'">Request package</a></article>').join('')+'</div></div></section>'}else if(location.pathname==='/contact/'){main.innerHTML='<section class="pagehead"><div class="wrap"><span class="eyebrow">Contact Tivione IPTV</span><h1>Choose the easiest way to reach us.</h1><p class="lead">For plans, setup help, reseller packages and account questions.</p></div></section><section><div class="wrap grid three"><article class="card"><h3>WhatsApp</h3><p>Fast help for subscriptions and reseller packages.</p><a class="button" href="https://wa.me/212670779271">Open WhatsApp</a></article><article class="card"><h3>Telegram</h3><p>Send a message through our Telegram channel.</p><a class="button" href="https://t.me/premiumiptvpanelscom">Open Telegram</a></article><article class="card"><h3>Email</h3><p>Send account or general enquiries by email.</p><a class="button" href="mailto:support@reselleriptv.com">Send email</a></article></div></section>'}else if(location.pathname==='/'){const hero=main.querySelector('.hero');if(hero){hero.innerHTML='<div class="wrap"><article class="slide active"><span class="eyebrow">Tivione IPTV</span><h1>Premium streaming.<br>Clear setup.<br>Better control.</h1><p class="lead">Choose a plan, set up your preferred player and discover flexible reseller tools.</p><div class="actions"><a class="button" href="/pricing/">Explore plans</a><a class="button alt" href="/reseller/">Explore reseller</a></div></article><article class="slide"><span class="eyebrow">Compatible devices</span><h1>One service.<br>Every screen.</h1><p class="lead">Find player resources and guided setup for TV, streaming devices, mobile and desktop.</p><div class="actions"><a class="button" href="/apps/">View apps</a><a class="button alt" href="/guides/">Read guides</a></div></article><article class="slide"><span class="eyebrow">For growing teams</span><h1>Build your reseller<br>workflow.</h1><p class="lead">Flexible credits, full API access and own-domain support for your next move.</p><div class="actions"><a class="button" href="/reseller/">View packages</a></div></article><div class="slider-dots"><button class="active"></button><button></button><button></button></div></div>';const slides=[...hero.querySelectorAll('.slide')],dots=[...hero.querySelectorAll('.slider-dots button')];let active=0;const show=n=>{slides[active].classList.remove('active');dots[active].classList.remove('active');active=n;slides[n].classList.add('active');dots[n].classList.add('active')};dots.forEach((d,i)=>d.onclick=()=>show(i));setInterval(()=>show((active+1)%slides.length),5000)}const extra=document.createElement('section');extra.innerHTML='<div class="wrap split-smart"><div><span class="eyebrow">Built for your next step</span><h2>Plans for viewers. Tools for resellers.</h2><p class="muted">Tivione IPTV brings clear plan options, device-friendly setup paths and reseller packages together in one place.</p><a class="button alt" href="/guides/">Find your setup guide →</a></div><article class="card"><span class="eyebrow">For growing businesses</span><h2>Reseller control without unnecessary complexity.</h2><p>Explore package options, flexible credit periods and support resources before building your plan.</p><ul class="list"><li>Flexible credit periods</li><li>API and domain support</li><li>Professional reseller workflow</li></ul><a class="button" href="/reseller/">Explore reseller packages</a></article></div></section><section><div class="wrap split-smart"><div><span class="eyebrow">Before you start</span><h2>A few things worth knowing.</h2><p class="muted">Simple answers before you choose a plan or player.</p></div><div class="faq-smart"><details><summary>Which devices are compatible?</summary><p>See the Apps and Guides pages for player and device options.</p></details><details><summary>How do I choose a plan?</summary><p>Compare durations on the Pricing page, then use the relevant request button.</p></details><details><summary>Can I explore reseller packages?</summary><p>Yes. The Reseller page explains each package and its server features.</p></details><details><summary>Where can I get setup help?</summary><p>Use the Contact page to select WhatsApp, Telegram or email.</p></details></div></div></section>';main.append(extra)}})();
